		public static void RegisterEventsHandler<T>(T handler) where T : global::LabApi.Events.CustomHandlers.CustomEventsHandler
		{
			global::System.Type type = handler.GetType();
			RegisterEvents(handler, type);
		}

		public static void UnregisterEventsHandler<T>(T handler) where T : global::LabApi.Events.CustomHandlers.CustomEventsHandler
		{
			foreach (global::System.Collections.Generic.KeyValuePair<global::System.Reflection.EventInfo, global::System.Delegate> internalEvent in handler.InternalEvents)
			{
				global::System.Reflection.EventInfo key = internalEvent.Key;
				global::System.Delegate value = internalEvent.Value;
				key.RemoveEventHandler(null, value);
			}
			handler.InternalEvents.Clear();
		}

		public static void CheckEvent<T>(T handler, global::System.Type handlerType, string methodDelegate, global::System.Type eventType, string eventName) where T : global::LabApi.Events.CustomHandlers.CustomEventsHandler
		{
			global::System.Reflection.MethodInfo[] methods = handlerType.GetMethods(global::System.Reflection.BindingFlags.Instance | global::System.Reflection.BindingFlags.Public);
			global::System.Reflection.MethodInfo methodInfo = null;
			global::System.Reflection.MethodInfo[] array = methods;
			foreach (global::System.Reflection.MethodInfo methodInfo2 in array)
			{
				if (methodInfo2.Name == methodDelegate && IsOverride(methodInfo2))
				{
					methodInfo = methodInfo2;
					break;
				}
			}
			if (!(methodInfo == null))
			{
				global::System.Reflection.EventInfo eventInfo = eventType.GetEvent(eventName);
				global::System.Delegate obj = global::System.Delegate.CreateDelegate(eventInfo.EventHandlerType, handler, methodInfo);
				eventInfo.AddEventHandler(null, obj);
				handler.InternalEvents.Add(eventInfo, obj);
			}
		}

		private static bool IsOverride(global::System.Reflection.MethodInfo method)
		{
			return method.GetBaseDefinition().DeclaringType != method.DeclaringType;
		}

